\item OpenAI, \emph{An integral scalar curvature bound for real simplicial volume}, 2026-10-05; citation key \texttt{OAI:An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026}. \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/v126-proof.pdf}{PDF (GitHub)}; \href{https://github.com/openai/math/raw/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/v126-proof.pdf}{PDF (direct)}; \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/README.md}{Manuscript page and citation}; \href{https://github.com/openai/math/blob/main/preprints/An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026/v126-proof.pdf}{Latest version}.
\item OpenAI, \emph{Positive scalar curvature forces rational inessentiality}, 2026-09-23; citation key \texttt{OAI:Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026}. \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/paper.pdf}{PDF (GitHub)}; \href{https://github.com/openai/math/raw/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/paper.pdf}{PDF (direct)}; \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/README.md}{Manuscript page and citation}; \href{https://github.com/openai/math/blob/main/preprints/Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026/paper.pdf}{Latest version}.
